using Astrea.BattleActions;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class PlayerCorruptionStats : CorruptionStats
{
	[Header("Stats")]
	[SerializeField]
	private bool debugStartingCorruption;

	[SerializeField]
	[ShowIf("debugStartingCorruption")]
	private int startingCorruption;

	[Header("Player Assets")]
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private CompanionEffectsList companionEffectsList;

	[Header("Events")]
	[SerializeField]
	private FloatEvent OnPlayerPurifiedCorrupted;

	private bool completelyCorrupted;

	private int healbotActivatedPurifyAmountOne;

	private int healbotActivatedPurifyAmountTwo;

	private int reliefActivatedPurifyAmount;

	private int afflictionActivatedPurifyAmount;

	private int forcefulStreamActivatedPurifyAmount;

	public bool CompletelyCorrupted => completelyCorrupted;

	public void SetCompletelyCorrupted(bool value)
	{
		completelyCorrupted = value;
	}

	public void Initialize()
	{
		maxCorruption = 7f;
		currentCorruption = (debugStartingCorruption ? startingCorruption : 0);
		OnPlayerPurifiedCorrupted.Raise(currentCorruption);
	}

	public void EndOfBattleInitialize()
	{
		playerCurrentRunes.ResetUsedActiveAndRefreshedRunes();
		currentCorruption = 0f;
		OnPlayerPurifiedCorrupted.Raise(currentCorruption);
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerPurifiedCorruptedCheckZenithRingOmenFeedback(currentCorruption);
	}

	[Button(null)]
	public void DamageDebug()
	{
		Corrupt(7, null);
	}

	public void OnResetPlayerCurrentCorruption()
	{
		currentCorruption = 0f;
		OnPlayerPurifiedCorrupted.Raise(currentCorruption);
	}

	public void OnLoseHeartAction()
	{
		(spriteControl as PlayerSpriteControl).SetOverrideIsDefeated(value: true);
		PlayerCompletelyCorrupted();
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	public override int Purify(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		amount = base.Purify(amount, source, corruptionPurifyModifierEnum, playSFX);
		if (amount > 0 && corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.RANDOMPURIFYRANDOMCONFUSE && unitEffects.IsEffectActiveAndDecreaseEffect(playerEffectsList.ResonantBuzzEffect, 1))
		{
			playerEffectsList.ResonantBuzzEffect.DealPurification(amount);
		}
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.HEALBOT)
		{
			if (healbotActivatedPurifyAmountOne == 0)
			{
				healbotActivatedPurifyAmountOne = amount;
			}
			else if (healbotActivatedPurifyAmountTwo == 0)
			{
				healbotActivatedPurifyAmountTwo = amount;
			}
		}
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.AFFLICTIONRELIEF)
		{
			reliefActivatedPurifyAmount = amount;
		}
		return amount;
	}

	public override int Corrupt(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CorruptedTimesAmount++;
		amount = ReferenceSingleton<CellariusOmensHandler>.Instance.OnPlayerCorruptedDenticleSuit(amount, source, corruptionPurifyModifierEnum);
		amount = ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptedDiademOfMadness(amount, corruptionPurifyModifierEnum, source);
		if (unitEffects.IsEffectActive(playerEffectsList.NegativeFieldEffect, activateFeedback: false) && playerEffectsList.NegativeFieldEffect.RedirectCorruption(unitEffects, amount, source))
		{
			return 0;
		}
		DodgeEffect dodgeEffect = effectsList.DodgeEffect;
		if (unitEffects.IsEffectActiveRemoveEffect(playerEffectsList.AutoDodgeEffect))
		{
			dodgeEffect.DodgeTriggered(unitEffects, GetCorruptionWithOffensiveModifiers(amount, corruptionPurifyModifierEnum), normalDodge: false, source);
			amount = -1;
		}
		else if (unitEffects.IsEffectActive(effectsList.SmokeBombEffect, activateFeedback: false))
		{
			if (dodgeEffect.CheckDodge(effectsList.SmokeBombEffect.DodgePercentage, unitEffects, normalDodge: false, GetCorruptionWithOffensiveModifiers(amount, corruptionPurifyModifierEnum), source))
			{
				unitEffects.IsEffectActive(effectsList.SmokeBombEffect);
				amount = -1;
			}
			else
			{
				amount = CheckDodge(amount, corruptionPurifyModifierEnum, source);
			}
		}
		else
		{
			amount = CheckDodge(amount, corruptionPurifyModifierEnum, source);
		}
		if (!dodgeEffect.CantTouchThisAchievementData.IsUnlocked() && amount != -1)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.DodgeInARowAmount = 0;
		}
		amount = base.Corrupt(amount, source, corruptionPurifyModifierEnum, playSFX);
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.AFFLICTIONRELIEF)
		{
			afflictionActivatedPurifyAmount = amount;
		}
		if (corruptionPurifyModifierEnum == CorruptionPurifyModifierEnum.FORCEFULSTREAM)
		{
			forcefulStreamActivatedPurifyAmount = amount;
		}
		return amount;
	}

	protected override int GetCorruptionAmountWithDefensiveModifiers(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum, GameObject source)
	{
		if (corruptionPurifyModifierEnum != CorruptionPurifyModifierEnum.ANOMALY)
		{
			int num = unitEffects.IsEffectActiveGetAmount(playerEffectsList.SkinHeveliusLinkEffect);
			amount = Mathf.Max(amount - num, 0);
		}
		return base.GetCorruptionAmountWithDefensiveModifiers(amount, corruptionPurifyModifierEnum, source);
	}

	protected override int GetCorruptionAmountWithCorruptionIncreaseModifiers(int amount)
	{
		if (amount > 0 && unitEffects.IsEffectActive(playerEffectsList.HurricaneActiveEffect))
		{
			amount *= 2;
		}
		return amount;
	}

	protected override void UpdateCorruption(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (currentCorruption < 0f)
		{
			ActivateOverpurifiedEffects();
		}
		if (currentCorruption == 6f)
		{
			ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnPlayerSixCorruptionOmens();
		}
		healbotActivatedPurifyAmountOne = 0;
		healbotActivatedPurifyAmountTwo = 0;
		reliefActivatedPurifyAmount = 0;
		afflictionActivatedPurifyAmount = 0;
		forcefulStreamActivatedPurifyAmount = 0;
		base.UpdateCorruption(corruptionPurifyModifierEnum);
		OnPlayerPurifiedCorrupted.Raise(currentCorruption);
		(unitEffects as PlayerEffects).OnPurifyEffectsBeforeCurrentCorruptionUpdate();
	}

	private void ActivateOverpurifiedEffects()
	{
		int num = afflictionActivatedPurifyAmount + forcefulStreamActivatedPurifyAmount + (int)oldCorruption;
		int num2 = -(int)currentCorruption;
		if (healbotActivatedPurifyAmountOne > 0 && healbotActivatedPurifyAmountTwo > 0 && reliefActivatedPurifyAmount > 0)
		{
			if (num < reliefActivatedPurifyAmount)
			{
				int num3 = reliefActivatedPurifyAmount - num;
				num2 -= num3;
				ReferenceSingleton<SothisOmensHandler>.Instance.ActivateSlateOfPlentyOmen(num3);
				num2 -= healbotActivatedPurifyAmountOne;
				companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(healbotActivatedPurifyAmountOne);
				companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(num2);
			}
			else
			{
				ActivateBothHealbotOverpurifiedEffects(num - reliefActivatedPurifyAmount, num2);
			}
		}
		else if (healbotActivatedPurifyAmountOne > 0 && healbotActivatedPurifyAmountTwo > 0)
		{
			ActivateBothHealbotOverpurifiedEffects(num, num2);
		}
		else if (healbotActivatedPurifyAmountOne > 0)
		{
			if (reliefActivatedPurifyAmount > 0)
			{
				if (num < reliefActivatedPurifyAmount)
				{
					int num4 = reliefActivatedPurifyAmount - num;
					num2 -= num4;
					ReferenceSingleton<SothisOmensHandler>.Instance.ActivateSlateOfPlentyOmen(num4);
					companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(num2);
				}
				else
				{
					companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(num2);
				}
			}
			else
			{
				companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(num2);
			}
		}
		else if (reliefActivatedPurifyAmount > 0)
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateSlateOfPlentyOmen(num2);
		}
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerAndSentinelsExceededPurify(-(int)currentCorruption);
	}

	private void ActivateBothHealbotOverpurifiedEffects(int corruptAmount, int purifyAmount)
	{
		if (corruptAmount < healbotActivatedPurifyAmountOne)
		{
			int num = healbotActivatedPurifyAmountOne - corruptAmount;
			purifyAmount -= num;
			companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(num);
			companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(purifyAmount);
		}
		else
		{
			companionEffectsList.HealbotEffect.PurificationExceedDealRandomEnemyPurification(purifyAmount);
		}
	}

	protected override void CorruptedMoreThanPurified()
	{
		if (currentCorruption == maxCorruption)
		{
			PlayerCompletelyCorrupted();
		}
		else
		{
			spriteControl.OnReceiveCorruption();
		}
	}

	protected override void PurifiedMoreThanCorrupted()
	{
		spriteControl.OnReceivePurify();
	}

	private void PlayerCompletelyCorrupted()
	{
		PlayerSpriteControl playerSpriteControl = spriteControl as PlayerSpriteControl;
		if (completelyCorrupted)
		{
			playerSpriteControl.OnReceiveCorruptionAndShake();
			return;
		}
		SetCompletelyCorrupted(value: true);
		playerSpriteControl.OnReceiveCorruptionAndLoseHeartPlayReceiveDamage();
	}

	public void IncreaseCorruptionToMax()
	{
		currentCorruption = maxCorruption - 1f;
		OnPlayerPurifiedCorrupted.Raise(currentCorruption);
	}

	public override bool IsDefeated()
	{
		return currentCorruption >= maxCorruption;
	}
}
